/* Valve verification renderer. Expects $valveCertificate, $valveLogs, $valveChecks. */
function valveV($x){return htmlspecialchars((string)($x??''),ENT_QUOTES,'UTF-8');}
function valveImgDataUri($path){
    $path=trim((string)$path); if($path==='') return '';
    $path=str_replace('\\','/',$path); $path=ltrim($path,'/');
    if(strpos($path,'public/')===0) $path=substr($path,7);
    $candidates=[__DIR__.'/'.$path, __DIR__.'/uploads/'.basename($path)];
    foreach($candidates as $full){
        if(is_file($full) && is_readable($full)){
            $mime='';
            if(function_exists('finfo_open')){ $fi=finfo_open(FILEINFO_MIME_TYPE); if($fi){$mime=finfo_file($fi,$full);finfo_close($fi);} }
            if(!$mime) $mime=@mime_content_type($full) ?: '';
            $data=@file_get_contents($full);
            if($mime && $data!==false) return 'data:'.$mime.';base64,'.base64_encode($data);
        }
    }
    return '';
}
$c=$valveCertificate;$logs=$valveLogs;$checks=$valveChecks;$testSig=valveImgDataUri($c['tested_signature']??'');$witSig=valveImgDataUri($c['witnessed_signature']??'');$stamp=valveImgDataUri($c['stamp_image']??'');
?>
